import Foundation

struct GuideSection: Identifiable { let id = UUID(); let title: String; let body: String }
struct Release: Identifiable { let id = UUID(); let version: String; let date: String; let items: [String] }
/// What is drawn next to a sign's meaning.
enum SignKind { case markBlack, markBlue, buttonFull, buttonPale, green, blue, coral, amber, dashedLine, redLine, dottedLine, greyBand, teal, paleBlueStretch, paleTealStretch, pointerLine }
struct GuideSign: Identifiable { let id = UUID(); let kind: SignKind; let name: String; let meaning: String }

enum Guide {
    static let howItWorks: [GuideSection] = [
        GuideSection(title: "What this app is for", body: "The Mac has no setting of its own for how fast its fans turn. AMS Fan Menu gives you one. It lives in the menu bar at the top of the screen and has no Dock icon.\n\nIt is made for a MacBook Pro 16-inch (2021, M1 Max). That Mac has two fans, Left and Right."),
        GuideSection(title: "The menu bar", body: "You see a small hand-drawn fan mark and no figure. The mark is black (white at night) while the Mac decides how fast the fans turn. It is blue while AMS Fan Menu runs the fans, which is true for every choice except Automatic.\n\nHover over the mark and it says who decides. Under that line it also gives the figures, for example \"Left 1,776 \u{00B7} Right 1,868 \u{00B7} Chip 72\u{00B0}\". A click opens the panel.\n\nIf the Mac ever moves the mark out of sight, to the far left, the app puts it back after 10 seconds.\n\nA right click (or a control-click) on the mark (0.7) shows a short menu: \"Automatic\", \"Cool for 10 min\", then \"Graphs\u{2026}\" and \"Settings\u{2026}\". While the Mac decides, a tick stands beside Automatic. \"Cool for 10 min\" gives Cool for 10 minutes and then the fans go back to the Mac. It does not change your own pick in the \"For\" line. A left click still opens the panel."),
        GuideSection(title: "The panel", body: "At the top is the header: the small app tile, the name, the version number and the gear button for Settings.\n\nBelow it, a line such as \"Left 1,776 \u{00B7} Right 1,868\" shows how fast each fan turns now, in turns a minute. It is fresh every second while the panel is open.\n\nThe next line, such as \"Chip 72\u{00B0} \u{00B7} Graphics 64\u{00B0} \u{00B7} Battery 36\u{00B0}\", shows the temperatures in degrees Celsius. Chip is the average of the processor cores.\n\nA second line, such as \"Storage 41\u{00B0} \u{00B7} Case 31\u{00B0}\", shows the Mac's built-in storage and the case under your hands, left and right of the trackpad.\n\nA block \"Power\" (teal) says, for example, \"Whole Mac 42 W\": what the whole Mac uses right now, in watts. Measured on 25 Nov 2026 at light work: about 42 W.\n\nA status line says \"The Mac decides\" or, for example, \"You decide: Cool\". Under the buttons is the line \"For\". At the bottom is a small graph of the last 15 minutes. Under it a caption says what it shows, for example \"Chip, last 15 minutes \u{00B7} tap for the large graph\". Before 0.6 it said \"Last 15 minutes \u{00B7} tap for the large graph\". In Settings you can pick another temperature for it."),
        GuideSection(title: "The six choices: the first four", body: "Under the status line you find six choices. The one in use is drawn in full colour with white words. The others are pale.\n\nAutomatic (green): the Mac decides, as if the app were not there. When the Mac is cool it often stops the fans completely, and the panel then shows 0.\n\nQuiet (blue): both fans are held at their lowest running speed, unless you changed it in Settings. This helps when the Mac is warm and would speed the fans up. The Mac gets warmer and may slow itself down.\n\nWhen the chip is cool, Quiet lets the fans stop, as Automatic does. The status line then says \"You decide: Quiet \u{00B7} fans resting\". If the Mac needs the fans again, Quiet takes them back at your Quiet speed. You can turn this off in Settings.\n\nCool (blue): half speed, unless you changed it in Settings.\n\nFull (blue): the top speed."),
        GuideSection(title: "The six choices: My speed and Follow temperature", body: "My speed (blue) has a slider with a percent figure. 0 % is the lowest speed, 100 % is the top. Both fans move together, each within its own range. Dragging the slider switches to My speed.\n\nFollow temperature (coral) has two sliders, Start (first 65\u{00B0}) and Full (first 95\u{00B0}). At or below Start the fans run at their lowest. At Full or above they run at their top. In between it is even.\n\nIt follows the Chip temperature, averaged over three readings. It changes the speed only when the change is at least 100 turns, so the fans do not keep hunting.\n\nStart can be 40\u{00B0} to 85\u{00B0} and Full 60\u{00B0} to 100\u{00B0}, in steps of 5\u{00B0}. They stay at least 10\u{00B0} apart: moving one pushes the other."),
        GuideSection(title: "Your own Quiet and Cool", body: "Quiet and Cool no longer have to be the speeds the app first picked. In Settings, under \"Your speeds\", you set them yourself.\n\nQuiet can be 0 % to 40 %. At first it is 0 %, which means the lowest speed.\n\nCool can be 30 % to 90 %. At first it is 50 %, which means half speed. Both go in steps of 5.\n\nThe words under the two buttons follow your pick: \"lowest speed\", \"half speed\", or for example \"40 % speed\".\n\nThe switch \"Quiet lets the fans stop\" is in the same place. At first it is on. While it is on, Quiet lets the fans rest when the chip is cool: after 30 seconds at 60\u{00B0} or less the app gives the fans to the Mac, which then stops them when it finds it cool enough. When the Mac runs a fan more than 150 turns faster than your Quiet speed for 4 seconds, the app takes the fans again and holds them at your Quiet speed. After that it holds them for at least 5 minutes before they may rest again, so they do not switch back and forth. This works the same with your own Quiet speed. With the switch off, Quiet always holds your Quiet speed and never stops the fans. If you switch it off during a rest, your Quiet speed comes back at once."),
        GuideSection(title: "Each fan's own range", body: "The app asks the Mac for each fan's own lowest and top speed. On this Mac the lowest is 1,499 for both fans. The top is 5,348 for the left fan and 5,776 for the right fan, in turns a minute.\n\n\"Lowest\" and \"top\" in every choice mean those figures, fan by fan. A speed is never below a fan's lowest or above its top.\n\nOnly the Mac itself can stop a fan completely. The app never asks for less than a fan's lowest running speed. When Quiet lets the fans rest, the app gives them to the Mac and the Mac stops them."),
        GuideSection(title: "A choice for a limited time", body: "Under the buttons is a line \"For\" with four picks: 10 min, 30 min, 1 hour and Until I change. It works with every choice except Automatic. The pick in use is in full colour.\n\nWhen the time is up, the Mac gets the fans back by itself and the choice goes to Automatic. The status line counts down, for example \"You decide: Cool \u{00B7} 8 min left\".\n\nTapping a choice, or a time, starts the time afresh. The app remembers your pick. At first it is \"Until I change\".\n\nAnother app can ask for a time of its own. The Cool and Full keys of AMS Deck Mate ask for 10 minutes. While such a time runs, the line shows it in full colour (10 min) and the status line counts down. When it is up, the choice goes to Automatic and the line shows your own pick again. Your pick is never changed by this. A tap on a time in the line takes over at once.\n\nA word when it ends (0.6): in Settings, the switch \"A word when a timed choice ends\" gives a notification when such a time is up. At first it is off. It counts for the times of the \"For\" line and for a time another app asked for. For example: \"Cool is over: chip 78\u{00B0} down to 61\u{00B0}. The Mac has the fans again.\" A choice shorter than 2 minutes says only \"Cool is over. The Mac has the fans again.\""),
        GuideSection(title: "The graphs", body: "At the bottom of the panel a small graph shows the last 15 minutes. A coral line is the chip temperature. The coral line is the chip temperature at first. In Settings, the section \"Small graph\" can show the battery or the case instead (see Settings). A blue line is always the fan speed, the average of both fans. A dashed line marks every moment the choice changed. While Quiet lets the fans rest, the blue line goes down to 0. That is true, not a fault.\n\nTap the small graph and the large graph opens in its own window. You can look at 15 minutes, 1 hour or 6 hours. It has six graphs, from top to bottom: Chip temperature, Graphics temperature, Battery temperature, Storage temperature, Case temperature and Fan speed. At first the last two temperatures (Storage and Case) are hidden, so you see four. Each temperature heading shows the figure right beside its name, then a small grey mark with the usual range, for example \"Chip temperature 56\u{00B0}\" and \"usual here 41\u{00B0} to 78\u{00B0}\". \"Done\" or Escape closes the window. The window is 560 x 768 points (before: 560 x 734).\n\nA row under the time pick says \"Show\" and has six small buttons: \"Chip\", \"Graphics\", \"Battery\", \"Storage\", \"Case\" and \"Fan speed\". A graph that is shown has its button in full colour (coral for temperatures, blue for Fan speed). A hidden one is pale. A tap shows or hides the graph. The last graph shown cannot be hidden. The window keeps its size: the graphs shown share the room, so fewer graphs are taller graphs. The app remembers your pick.\n\nThe Fan speed graph shows the speed of each fan, Left and Right. At each dashed line it names the change, for example \"Cool\". A pale blue stretch covers every time in which a choice other than Automatic was on. The dashed lines and the names stay. A pale teal stretch in the Battery graph covers every time in which the battery was charging, so you see why it warms. Beside the heading a small teal mark and the grey word \"charging\" say what the teal means. While the battery charges at this moment, the word is \"charging now\". Before 0.6 the Battery graph showed only the temperature, the grey usual band and the two level lines. The app notes whether the battery charges with every reading, so the stretch starts with the update to 0.6. Readings kept before 0.6 do not have it.\n\nWhere the Mac slept or the app was not running, the line has a gap. In every graph the gap now carries a grey word, \"asleep\" or \"not running\", when it is wide enough for the word. In the 6 hours view a short sleep is too narrow, and the gap stays empty. \"Not running\" means the app was quit, updated, or the Mac was restarted. The app knows the reason only from 0.6 on. Older gaps, and a sleep the Mac did not announce, stay empty.\n\nThe scale of the Chip graph reaches up to at least 120\u{00B0}, the Graphics graph up to at least 110\u{00B0}, and the Battery graph up to at least 50\u{00B0}, so the level lines are always in view.\n\nThe app notes one reading of the temperatures (chip, graphics, battery, storage and case), the power and the fan speed every 5 seconds, also while the panel is closed. It keeps six hours, and they survive quitting the app. They are saved on this Mac only. Readings kept before 0.4 have only the chip, and readings kept before 0.5 lack storage, case and power, so those graphs start empty and fill from the update on. Storage and Case have the grey \"usual\" band but no level lines. Each reading also notes whether the battery charges (from 0.6). While the Mac sleeps or the app is not running there are no readings, and the line has a gap there.\n\nAmber dots (0.7): in the large window a small amber dot marks each moment a notice was sent. The heat notice and \"Too hot\" stand in the Chip graph, the battery heat notice in the Battery graph, and a fan falling short in the Fan speed graph. The dots are kept for 6 hours, like the readings. Notices sent before 0.7 have no dot."),
        GuideSection(title: "The level lines", body: "In the large graph, thin flat lines cross a temperature graph. Each has its words at the right end. They are solid, so they cannot be mixed up with the upright dashed lines.\n\nChip graph:\nAmber, \"Heat notice 90\u{00B0}\" (or the level you picked in Settings, for example \"Heat notice 85\u{00B0}\"): from here the heat notice counts its 5 minutes. With the switch \"Heat notice\" off, this line is not drawn.\nRed, \"Too hot 100\u{00B0}\": the app's own safety rule. When the hottest core is at 100\u{00B0} for 15 seconds and Full is not on, the app gives the fans back to the Mac.\nGreen, \"Fans at full in Automatic \u{00B7} seen at N\u{00B0}\": this one the app learns on this Mac. It notes the chip temperature at the moment the Mac itself takes the fans to full (90 % of the top speed or more). That is in Automatic, or while Quiet lets the fans rest. Each new time replaces the old figure. Until it has happened there is no green line, and grey words beside the heading say \"fans at full in Automatic: not seen yet\".\n\nTwo more lines in the Chip graph are only rough. They are dotted and grey, and their words are grey and at the LEFT end, so they cannot be mixed up with the solid coloured lines:\nGrey dotted, \"Reports: fans speed up at about 95\u{00B0}\"\nGrey dotted, \"Reports: chip slows itself at about 100\u{00B0} to 110\u{00B0}\" (the line is drawn at 105\u{00B0}, the middle)\nThese come from what other owners of this kind of Mac have written on the web. They are not from Apple and not measured on this Mac. They may be wrong for this Mac. For comparison, measured on this Mac on 25 Nov 2026: in Automatic the fans were still at about 1,590 turns a minute with the chip at 90\u{00B0} to 93\u{00B0}. When the app has learned the green line on this Mac, trust the green line over the reports.\n\nBattery graph:\nAmber, \"Apple's limit for the room 35\u{00B0}\": Apple says to use a Mac laptop where it is 10\u{00B0} to 35\u{00B0}. That is the room, not the battery itself, but it is the only figure Apple gives.\nRed, \"Charging may stop about 44\u{00B0}\": an independent tester measured this once, on another Apple laptop. It is not an Apple figure, so it says \"about\".\n\nGraphics, Storage and Case graphs: no level lines and no rough lines. Apple gives no figures and the app has no rule for them.\n\nAll five temperature graphs have a soft grey band: the usual range on this Mac. The small grey mark beside the heading, with words such as \"usual here 41\u{00B0} to 78\u{00B0}\", says what it is. It is the range that holds the middle 80 % of all readings kept, up to six hours. It appears after 30 minutes of readings.\n\nThe honest limits: Apple publishes no figure for the temperature at which the chip slows itself, at which the Mac takes the fans to full, or at which the Mac turns itself off. The rough lines are only what owners report. There is still no line for \"the Mac turns itself off\": not even a report gives a figure. The window says what the lines mean in one line at the bottom: \"Dotted grey = owners' reports, not Apple \u{00B7} no figure for when the Mac turns itself off\"."),
        GuideSection(title: "Pointing at a graph", body: "Move the pointer over any graph in the large window. A thin upright solid line marks that moment in all graphs shown, with a small dot on each line.\n\nWhile you point, each heading shows the figure at that moment instead of the figure now, followed by grey words such as \"at 14:20\" (with seconds in the 15 minutes view, \"at 14:20:35\"). The Fan speed heading then says, for example, \"Left 1,580 \u{00B7} Right 1,640 at 14:20\".\n\nWhere there is a gap (the Mac slept or the app was not running) the figure is \"–\". From 0.6, when the app knows why, the headings say it instead, for example \"asleep at 14:20\" or \"not running at 14:20\". Where it does not know, the figure is still \"–\".\n\nMove the pointer away and everything is as before.\n\nPoint at an amber dot (0.7) and the heading of that graph shows the words of the notice, for example \"Heat notice: chip 90\u{00B0} or more for 5 min \u{00B7} Xcode\", instead of the time."),
        GuideSection(title: "First use and the helper", body: "Setting the fans needs the Mac's deepest rights. The first time you tap a choice other than Automatic, an amber note says \"Setting the fans needs your OK once\", with a button \"Allow fan control\u{2026}\".\n\nThe Mac then asks for your Mac password. That is the Mac's own dialog. The app never sees the password.\n\nThis puts a small helper on the Mac. The helper takes orders only from AMS Fan Menu, and only fan speeds inside each fan's own range.\n\nAfter an app update the note may ask once more (\"Update the helper\u{2026}\"). In Settings, \"Remove the helper\u{2026}\" takes it away again. The updates to 0.2, 0.3, 0.3.1 and 0.4 need no password, because the helper did not change."),
        GuideSection(title: "While a choice is on", body: "The Mac would otherwise take the fans back, so while a choice is on the app repeats it to the Mac every 3 seconds.\n\nIf you switch to Automatic, the app hands the fans straight back and the Mac decides again."),
        GuideSection(title: "The heat notice", body: "While the Mac decides, the app also keeps an eye on the chip. When it has been at your level or more for 5 minutes, a notification says so. It has a button \"Switch to Cool\".\n\nYou get this notice at most once every 30 minutes.\n\nIn Settings, the switch \"Heat notice\" turns it off. At first it is on. Under it a row \"From\" has four picks: 80\u{00B0}, 85\u{00B0}, 90\u{00B0} and 95\u{00B0}. At first it is 90\u{00B0}, as before. The notice counts its 5 minutes from that level. The amber line in the Chip graph moves with it (\"Heat notice 85\u{00B0}\"). With the switch off there is no amber line in the Chip graph. Before 0.5 the line was always there.\n\nThe notice names the app working hardest at that moment (0.7), for example: \"The chip has been at 90\u{00B0} or more for 5 minutes. Working hardest: Xcode.\" An app's helpers count with the app, so Chrome's many helpers count as one, Chrome. Two things are never named: the Mac's own cooling work (it is called kernel_task) and Fan Menu itself. If no app uses at least 20 % of one processor core, nothing is named and the notice reads as before. The \"Too hot\" notice and its line in What happened name the app too."),
        GuideSection(title: "Fan check-up", body: "A button in Settings (0.7), in the section \"Fan check-up\" (blue heading): \"Check the fans\". Each fan is asked for its top speed for 10 seconds. A fan that reaches 90 % of its top is fine.\n\nThe result stands under the button, for example \"18:52: Both fans fine \u{00B7} Left 5,310 of 5,348 \u{00B7} Right 5,750 of 5,776\". The same line is in What happened. If a fan falls short, the line says which one, for example \"Left fan fell short\".\n\nAfterwards the fans do what they did before. In Automatic the app gives them back to the Mac. If a choice of yours was on, it carries on.\n\nThe check stops early, and the fans go back at once, when you tap a new choice, when the Mac goes to sleep, or when you quit the app. The line then says why it stopped. The fans are loud for those 10 seconds. That is the point."),
        GuideSection(title: "A fan falling short", body: "While the app runs the fans (not while Quiet lets the fans rest), it watches that they do what was asked (0.7). If a fan stays below 80 % of the speed asked for, for 30 seconds, three things happen: a notification, for example \"The Right fan turned at 2,100 though 3,600 was asked, for 30 seconds. Dust or wear can do that; the fan check-up in Settings tells more.\", a line in What happened, and an amber dot in the Fan speed graph. At most one such notification in 6 hours.\n\nA new ask gives the fans their time afresh: the 30 seconds count from the moment the speed asked for changed."),
        GuideSection(title: "Battery heat notice", body: "While the Mac decides, the app also watches the battery. When it has been above 35\u{00B0} for 10 minutes, a notification says, for example, \"The battery has been above 35\u{00B0} for 10 minutes (now 37\u{00B0}).\" You get it at most once an hour. While the Mac decides it has the button \"Switch to Cool\".\n\nIn Settings, the switch \"Battery heat notice\" turns it off. At first it is on. 35\u{00B0} is the amber line in the Battery graph. \"What happened\" notes \"Battery heat notice: the battery was above 35\u{00B0} for 10 minutes\"."),
        GuideSection(title: "Quiet during calls", body: "A switch in Settings. At first it is off. When an app has used the microphone for 15 seconds, such as a video call, the app switches to Quiet. A short dictation does not count. The status line says \"You decide: Quiet (during a call)\".\n\nWhen the microphone has been free for 30 seconds, the choice you had before comes back. That includes Automatic.\n\nIf you tap a choice yourself during the call, your tap wins and nothing is put back.\n\nThe fans may rest then too, if \"Quiet lets the fans stop\" is on and the chip is cool.\n\nA video call makes the Mac warm. With the fans at their lowest it may reach the too-hot limit. Then the Mac gets the fans back, as always."),
        GuideSection(title: "Quiet hours", body: "A switch in Settings, \"Quiet hours\". At first it is off. It has two times, \"From 22:00\" and \"To 07:00\" at first. Between the two times Quiet comes on by itself. Afterwards the choice from before comes back, or the Mac gets the fans again if it had them. The status line says \"You decide: Quiet (quiet hours)\". The same time twice means no quiet hours.\n\nThe fine print:\nIt lasts as long as the hours, whatever the \"For\" line says.\nYour own tap during the hours wins until they are over.\nIf the Mac gets too hot (100\u{00B0}), it gets the fans and the hours leave them alone for that night.\nOn battery, with \"On battery: the Mac decides\" on, the Mac keeps the fans.\nDuring a call's Quiet nothing changes, and the hours take over when the call ends.\nAfter sleep inside the hours, Quiet comes on again.\nIt needs the fan control helper to be in place.\n\n\"What happened\" notes \"Quiet hours began: Quiet\" and \"Quiet hours ended: Cool again\", or \"Quiet hours ended: the Mac has the fans again\"."),
        GuideSection(title: "On battery: the Mac decides", body: "A switch in Settings. At first it is on. When you pull the power cable while a choice is on, the fans go back to the Mac. The status line says \"The Mac decides (on battery)\".\n\nWhen the cable is back in, your choice comes back.\n\nIf you tap a choice yourself while on battery, your tap wins."),
        GuideSection(title: "Choice back after sleep", body: "A switch in Settings. At first it is off. Sleep still hands the fans to the Mac, always.\n\nWith the switch on, the app puts your choice back about 5 seconds after the Mac wakes.\n\nWith the switch off, the app stays on Automatic after waking, and an amber note says so."),
        GuideSection(title: "Safety: four rules", body: "1. Too hot. If the hottest processor core is at 100\u{00B0} or more for 15 seconds while Quiet, Cool, My speed or Follow temperature is on, the app gives the fans back to the Mac and switches to Automatic. An amber note says, for example, \"Too hot (101\u{00B0}). The Mac has the fans again.\" and you get a notification. Full is left alone, because it is already the top speed.\n\n2. Quit, sleep and restart hand the fans back to the Mac. Quit and restart always leave the app on Automatic. After sleep the app stays on Automatic too, unless you turned on \"Choice back after sleep\".\n\n3. If the app ever stops unexpectedly, the helper gives the fans back by itself after 20 seconds. When the app comes back, it asks the helper at once to give the fans back, so the screen and the fans agree.\n\n4. A speed is never below a fan's lowest or above its top.\n\nFrom 0.7 the \"Too hot\" notice, and its line in \"What happened\", also name the app working hardest, in the same way as the heat notice."),
        GuideSection(title: "What the app remembers", body: "It remembers your My speed percentage and your Start and Full temperatures. It remembers your own Quiet and Cool speeds and the time you picked in the \"For\" line. It remembers the switches in Settings: the heat notice and its level (80\u{00B0}, 85\u{00B0}, 90\u{00B0} or 95\u{00B0}), the battery heat notice, quiet hours with their two times, \"A word when a timed choice ends\", and the others. It also remembers which graphs you show in the large window and which temperature the small graph shows.\n\nIt does not remember which choice was in use. After every start the Mac decides.\n\nIt keeps the graph readings (the temperatures, the power, whether the battery charges and the fan speed) for six hours, and the times in which the Mac slept or the app was not running (with the reason), the chip temperature where the Mac last took the fans to full in Automatic, and the list \"What happened\". It keeps the figures of \"The last 7 days\" (today and the 7 days before). All of this stays on this Mac only.\n\nThe app also keeps a diary of what it did: times, choices and speeds, nothing personal. The diary stays on this Mac only.\n\nFrom 0.7 it also keeps the notices that were sent, for the amber dots, for six hours, and the last result of the fan check-up while the app runs."),
        GuideSection(title: "What happened", body: "The fourth tab in Settings, \"What happened\", starts with the block \"The last 7 days\" (see below). Under it is the list of the last 20 things the app did. The newest is first, and each has its time, in plain words.\n\nFor example: \"Cool for 10 minutes\", \"The time was up: the Mac has the fans again\", \"Too hot (101\u{00B0}): the Mac has the fans again\", \"A call began: Quiet\", \"On battery: the Mac has the fans again\", \"Battery heat notice: the battery was above 35\u{00B0} for 10 minutes\", \"Quiet hours began: Quiet\" and \"Quiet hours ended: Cool again\".\n\nWas the choice worth it? When a choice of yours ends after 2 minutes or more, the list gets a line such as \"Cool for 10 min: chip 78\u{00B0} down to 61\u{00B0}\", \"Quiet for 1 h 5 min: chip 60\u{00B0} up to 71\u{00B0}\" or \"Full for 2 h: chip stayed at 70\u{00B0}\". It stands just before the line that says why the choice ended.\n\nThe list stays on this Mac only. The notification for a timed choice (see \"A choice for a limited time\") is not a line in this list.\n\nFrom 0.7 it also lists the heat notice with the app named, the result of the fan check-up, and a fan falling short."),
        GuideSection(title: "The last 7 days", body: "At the top of the \"What happened\" tab a block \"The last 7 days\" has four rows, for example:\nHottest 93\u{00B0} \u{00B7} Tue 14:20\nAt 90\u{00B0} or more 12 min\nFans turning 5 h 10 min\nA choice of yours on 1 h 5 min\n\nUntil seven days have figures, a grey line says \"Counted since 25 Nov\". Counting starts with the update to 0.5, so earlier days are not in it.\n\nThe figures are kept on this Mac only, for today and the 7 days before."),
        GuideSection(title: "Settings", body: "Open Settings with the gear button in the panel. It has four tabs: \"Settings\", \"What happened\", \"How it works\" and \"What's new\".\n\nThe \"Settings\" tab has \"Open at login\". While it is on, the app also comes back by itself if it ever stops unexpectedly. It has \"Your speeds\" for Quiet and Cool.\n\nUnder \"Your speeds\" it has the switch \"Quiet lets the fans stop\". The section \"Small graph\" (coral heading) has the row \"Shows\" with three picks: \"Chip\", \"Battery\" and \"Case\". At first it is Chip, as before. The section \"By itself\" has the rules that act by themselves: \"Heat notice\" with its row \"From\" (80\u{00B0}, 85\u{00B0}, 90\u{00B0} or 95\u{00B0}), \"Battery heat notice\", \"Quiet during calls\", \"Quiet hours\" with its two times \"From\" and \"To\", \"On battery: the Mac decides\" and \"Choice back after sleep\" and \"A word when a timed choice ends\" (off at first). It shows the state of the fan control helper, with \"Remove the helper\u{2026}\". It has \"Quit AMS Fan Menu\" and \"Done\". Escape also closes the window. The version number is shown too.\n\nFrom 0.7 the Settings tab has the section \"Fan check-up\" (blue heading) with the button \"Check the fans\" (see \"Fan check-up\"). The heat notice has one more line of words: it names the app working hardest."),
        GuideSection(title: "For AMS Deck Mate", body: "AMS Deck Mate can ask for a choice, and it can read which choice is on. From 0.6 there is one more thing. Fan Menu writes its newest figures into a small file every 5 seconds. The file stays on this Mac. So AMS Deck Mate from version 0.21 can show \"Chip 56\u{00B0}\" live on a key of the AMS Deck. A press on that key opens Fan Menu's large graphs.\n\nThere is nothing to set in Fan Menu.\n\nIf the figures are older than 30 seconds, for example while the Mac sleeps, the key shows no figure.\n\nFrom 0.7 there is a second live key: AMS Deck Mate 0.22 can show \"Fans 1,650\" (the speed of the fans in turns a minute), or \"Fans off\" when they are stopped. It reads the same file, the figures for the fans. A press on that key opens the large graphs. Fan Menu itself did not change for this, so there is again nothing to set."),
        GuideSection(title: "Good to know: the limits", body: "The app can never set a fan below its lowest running speed, 1,499 on this Mac. Only the Mac itself can stop a fan.\n\nSince 0.3, Quiet is never louder than Automatic. When the chip is cool, Quiet gives the fans to the Mac, which stops them (the fans are resting). When the Mac runs them faster, Quiet takes them back and holds them at your Quiet speed, at least 1,499. With \"Quiet lets the fans stop\" off, Quiet always holds your Quiet speed, and Automatic can be quieter, because the Mac stops the fans when it is cool. Quiet is for a warm Mac whose fans would otherwise speed up.\n\nQuiet makes the Mac warmer, and the Mac may slow itself down to cool off.\n\nThe Mac still protects itself. If it gets too hot, it can act on its own, whatever you chose.\n\nWhile the Mac sleeps or the app is not running, nothing is noted, so the graph has a gap. From 0.6 the gap says \"asleep\" or \"not running\" when the app knows and the gap is wide enough.\n\nThe app does not know whether a battery was charging before 0.6, so the pale teal stretch starts with the update.\n\nApple documents none of the sensors behind Storage, Case and Power. The names are the ones fan tools commonly use (storage TH0a and TH0b, case Ts0P and Ts1P, power PSTR). The figures are the Mac's own, but what they mean is by common use. Measured on 25 Nov 2026: storage 31\u{00B0}, case 30\u{00B0}, whole Mac about 42 W at light work.\n\nThe app is installed straight on the Mac, not through TestFlight.")
    ]

    static let signs: [GuideSign] = [
        GuideSign(kind: .markBlack, name: "Black fan mark (white at night)", meaning: "The Mac decides how fast the fans turn."),
        GuideSign(kind: .markBlue, name: "Blue fan mark", meaning: "Your choice is on, not Automatic. It stays blue while Quiet lets the fans rest (\"fans resting\")."),
        GuideSign(kind: .buttonFull, name: "A button in full colour", meaning: "The choice or pick in use now: a choice, a time in the \"For\" line, a time in the large graph, a graph that is shown, the heat notice level. Quiet stays in full colour while the fans rest."),
        GuideSign(kind: .buttonPale, name: "A pale button", meaning: "A choice or pick you can tap. Also a graph that is hidden."),
        GuideSign(kind: .green, name: "Green", meaning: "The Mac decides (Automatic). Also the line in a graph where the Mac itself took the fans to full."),
        GuideSign(kind: .blue, name: "Blue", meaning: "A fan speed you set, and the fan speed line in the graph."),
        GuideSign(kind: .coral, name: "Coral", meaning: "Temperature (words, sliders, and the line of each of the five temperature graphs: Chip, Graphics, Battery, Storage and Case)."),
        GuideSign(kind: .amber, name: "Amber", meaning: "A note that needs your eye, sometimes with a button. Also the line in a graph from where a temperature needs your eye: in the Chip graph the heat notice level you picked, in the Battery graph Apple's limit of 35\u{00B0}."),
        GuideSign(kind: .amber, name: "Amber dot in a graph", meaning: "A notice was sent here. Point at it to read it."),
        GuideSign(kind: .dashedLine, name: "Dashed line in a graph", meaning: "The moment the choice changed. It stands upright in every graph; the Fan speed graph names the change."),
        GuideSign(kind: .redLine, name: "Red line in a graph", meaning: "Too hot: from here something protects itself. The app gives the fans back to the Mac, or the battery may stop charging. Red is used nowhere else."),
        GuideSign(kind: .dottedLine, name: "Dotted grey line in a graph", meaning: "A rough figure from other owners' reports. It is not from Apple and not measured on this Mac, so it may be wrong for this Mac. Its grey words are at the left end."),
        GuideSign(kind: .teal, name: "Teal", meaning: "Electric power: what the whole Mac uses (panel), and, pale in the Battery graph, the time the battery was charging."),
        GuideSign(kind: .paleBlueStretch, name: "Pale blue stretch in the Fan speed graph", meaning: "A choice of yours was on during that time."),
        GuideSign(kind: .paleTealStretch, name: "Pale teal stretch in the Battery graph", meaning: "The battery was charging then."),
        GuideSign(kind: .pointerLine, name: "Thin upright solid line that follows the pointer", meaning: "The moment you point at. Every graph shown marks it, and each heading gives the figure for that moment."),
        GuideSign(kind: .greyBand, name: "Grey band in a graph", meaning: "The usual range on this Mac: it holds the middle 80 % of the readings kept. The same grey mark stands beside the heading, with the figures.")
    ]

    static let whatsNew: [Release] = [
        Release(version: "0.7", date: "25 Nov 2026", items: [
            "New: the heat notice names the app working hardest. Before, it said only \"The chip has been at 90\u{00B0} or more for 5 minutes.\" Now it adds, for example, \"Working hardest: Xcode.\" An app's helpers count with the app (Chrome's many helpers count as Chrome). The Mac's own cooling work (kernel_task) and Fan Menu itself are never named. Below 20 % of one processor core nothing is named, and the notice reads as before. The \"Too hot\" notice and its line in What happened name the app too.",
            "New: a fan check-up. In Settings a new section \"Fan check-up\" (blue heading) has the button \"Check the fans\". Each fan is asked for its top speed for 10 seconds. A fan that reaches 90 % of its top is fine. The result shows under the button and in What happened, for example \"18:52: Both fans fine \u{00B7} Left 5,310 of 5,348 \u{00B7} Right 5,750 of 5,776\". Afterwards the fans do what they did before: in Automatic the Mac gets them back, and a choice of yours carries on. A new choice, sleep or quitting stops the check early and gives the fans back.",
            "New: a fan that falls short. While the app runs the fans (not while Quiet lets the fans rest), a fan that stays below 80 % of the speed asked for, for 30 seconds, brings a notification (at most once in 6 hours), a line in What happened and an amber dot in the Fan speed graph. A new ask gives the fans their time afresh. Before, nothing told you.",
            "New: amber dots in the large graphs. A dot marks where a notice was sent: the heat notice and \"Too hot\" in the Chip graph, the battery heat notice in the Battery graph, a fan falling short in the Fan speed graph. Point at a dot and the heading of that graph shows the notice's words. The dots are kept for 6 hours, like the readings. Notices sent before 0.7 have no dot.",
            "New: a right click on the fan mark. A right click (or a control-click) shows a short menu: \"Automatic\", \"Cool for 10 min\", \"Graphs\u{2026}\" and \"Settings\u{2026}\". A tick stands beside Automatic while the Mac decides. \"Cool for 10 min\" does not change your own pick in the \"For\" line. A left click still opens the panel, as before.",
            "For other apps: AMS Deck Mate 0.22 has a second live key, \"Fans 1,650\" (\"Fans off\" when the fans are stopped). A press opens the graphs. Fan Menu did not change for this: it already wrote the speed of the fans into its small file.",
            "Unchanged: the six choices, the level lines, the safety rules and the helper. No new password is needed.",
            "Changed: How it works has new words in The menu bar, The heat notice, The graphs, Pointing at a graph, Safety: four rules, What happened, What the app remembers, Settings and For AMS Deck Mate, and two new sections, \"Fan check-up\" and \"A fan falling short\". Signs in this app has a new line: an amber dot in a graph (a notice was sent here; point at it to read it). It is the same amber as before: a note.",
        ]),
        Release(version: "0.6", date: "25 Nov 2026", items: [
            "New: charging in the Battery graph. Before, the Battery temperature graph showed the temperature, the grey usual band and two level lines. Now a pale teal stretch covers every time in which the battery was charging, so you see why it warms. Beside the heading a small teal mark and the grey word \"charging\" say what the teal means (\"charging now\" while it charges at this moment). The app notes whether the battery charges with every reading, every 5 seconds. Readings kept before 0.6 do not have it, so the stretch starts with this update.",
            "New: a gap says why. Before, while the Mac slept or the app was not running, the graphs just had a gap. Now the gap carries a grey word in every graph, \"asleep\" or \"not running\", when it is wide enough for the word. In the 6 hours view a short sleep is too narrow and stays empty. \"Not running\" means the app was quit, updated, or the Mac was restarted.",
            "Changed: pointing into such a gap, the headings now say \"asleep at 14:20\" instead of \"–\".",
            "Good to know: the app knows the reason only from this update on. Older gaps, and a sleep the Mac did not announce, stay empty (and the headings still say \"–\").",
            "New: the small graph in the panel may show another temperature. A new section \"Small graph\" (coral heading) in Settings has the row \"Shows\" with three picks: \"Chip\", \"Battery\" and \"Case\". At first it is Chip, as before. The blue line is always the fan speed.",
            "Changed: the caption under the small graph now names it: \"Chip, last 15 minutes \u{00B7} tap for the large graph\". Before it said \"Last 15 minutes \u{00B7} tap for the large graph\".",
            "New: a word when a timed choice ends. A new switch in Settings, in the section \"By itself\": \"A word when a timed choice ends\", off at first. When such a time is up, a notification says, for example, \"Cool is over: chip 78\u{00B0} down to 61\u{00B0}. The Mac has the fans again.\" A choice shorter than 2 minutes says only \"Cool is over. The Mac has the fans again.\" It counts for the times of the \"For\" line and for a time another app asked for (the Cool and Full keys of AMS Deck Mate last 10 minutes). Before, the end of a timed choice came with no notification.",
            "New: a key with the chip temperature for AMS Deck Mate. Fan Menu now writes its newest figures into a small file every 5 seconds. The file stays on this Mac. So AMS Deck Mate from version 0.21 can show \"Chip 56\u{00B0}\" live on a key of the AMS Deck, and a press on that key opens Fan Menu's large graphs. Nothing to set in Fan Menu. Before, Deck Mate could only ask for a choice and read which choice is on.",
            "Unchanged: the six choices, the level lines and the helper. No new password is needed.",
            "Changed: How it works has new words in The panel, The graphs, Pointing at a graph, A choice for a limited time, What the app remembers, Settings and Good to know, and a new section \"For AMS Deck Mate\". Signs in this app has a new sign: a pale teal stretch in the Battery graph (the battery was charging then). Teal now covers electric power: what the whole Mac uses (panel), and, pale in the Battery graph, the time the battery was charging. The grey words \"asleep\" and \"not running\" need no sign: they say it themselves.",
        ]),
        Release(version: "0.5", date: "25 Nov 2026", items: [
            "New: the figure where you point. Before, a heading in the large graph window showed only the figure now. Now, when you move the pointer over any graph, a thin upright solid line marks that moment in all graphs shown, with a small dot on each line. Each heading then shows the figure at that moment instead of the figure now, followed by grey words such as \"at 14:20\" (with seconds in the 15 minutes view, \"at 14:20:35\"). The Fan speed heading says, for example, \"Left 1,580 \u{00B7} Right 1,640 at 14:20\". Where there is a gap (the Mac slept or the app was not running) the figure is \"–\". Move the pointer away and everything is as before.",
            "New: colour while a choice is on. In the Fan speed graph, a pale blue stretch now covers every time in which a choice other than Automatic was on. The dashed lines and the names of the changes stay.",
            "New: choose which graphs show. A new row under the time pick says \"Show\" and has six small buttons: \"Chip\", \"Graphics\", \"Battery\", \"Storage\", \"Case\" and \"Fan speed\". A graph that is shown has its button in full colour (coral for temperatures, blue for Fan speed). A hidden one is pale. A tap shows or hides the graph. The last graph shown cannot be hidden. At first Chip, Graphics, Battery and Fan speed are shown, and Storage and Case are hidden. The app remembers your pick.",
            "Changed: the large graph window is a little taller than before, for the new row. It keeps its size whatever you show: the graphs shown share the room, so fewer graphs are taller graphs. Before, there were always four graphs.",
            "New: was the choice worth it? When a choice of yours ends after 2 minutes or more, \"What happened\" gets a line such as \"Cool for 10 min: chip 78\u{00B0} down to 61\u{00B0}\", \"Quiet for 1 h 5 min: chip 60\u{00B0} up to 71\u{00B0}\" or \"Full for 2 h: chip stayed at 70\u{00B0}\". It stands just before the line that says why the choice ended.",
            "New: the week in figures. At the top of the \"What happened\" tab a block \"The last 7 days\" has four rows: \"Hottest 93\u{00B0} \u{00B7} Tue 14:20\", \"At 90\u{00B0} or more 12 min\", \"Fans turning 5 h 10 min\" and \"A choice of yours on 1 h 5 min\". Until seven days have figures, a grey line says \"Counted since 25 Nov\". Counting starts with this update, so earlier days are not in it. The figures are kept on this Mac only (today and the 7 days before).",
            "New: power. The panel has a new block \"Power\" (teal) with a line such as \"Whole Mac 42 W\": what the whole Mac uses right now, in watts. Measured on 25 Nov 2026 at light work: about 42 W.",
            "New: more temperatures. The panel's Temperature block has a second line, \"Storage 41\u{00B0} \u{00B7} Case 31\u{00B0}\". Storage is the Mac's built-in storage. Case is the case under your hands, left and right of the trackpad. Both also have a graph each (\"Storage temperature\", \"Case temperature\"), hidden at first (see the Show row). They have the grey \"usual\" band but no level lines. Measured on 25 Nov 2026: storage 31\u{00B0}, case 30\u{00B0}.",
            "Good to know: Apple documents none of these sensors (storage, case, power). The names are the ones fan tools commonly use (storage TH0a and TH0b, case Ts0P and Ts1P, power PSTR). So the figures are the Mac's own, but what they mean is by common use. Readings kept before 0.5 lack them, so the Storage and Case graphs fill from the update on.",
            "New: battery heat notice. A new switch in Settings, \"Battery heat notice\", on at first. A notification comes when the battery has been above 35\u{00B0} for 10 minutes, at most once an hour: \"The battery has been above 35\u{00B0} for 10 minutes (now 37\u{00B0}).\" While the Mac decides it has the button \"Switch to Cool\". \"What happened\" gets \"Battery heat notice: the battery was above 35\u{00B0} for 10 minutes\". 35\u{00B0} is the amber line in the Battery graph.",
            "New: your own heat notice level. Under the \"Heat notice\" switch a new row \"From\" has four picks: 80\u{00B0}, 85\u{00B0}, 90\u{00B0} and 95\u{00B0} (at first 90\u{00B0}, as before). The notice counts its 5 minutes from that level. The amber line in the Chip graph moves with it (\"Heat notice 85\u{00B0}\").",
            "Changed: with the \"Heat notice\" switch off, the Chip graph now has no amber line. Before, the line was always there.",
            "New: quiet hours. A new switch in Settings, \"Quiet hours\", off at first, with two times, \"From 22:00\" and \"To 07:00\". Between the two times Quiet comes on by itself. Afterwards the choice from before comes back, or the Mac gets the fans again if it had them. The status line says \"You decide: Quiet (quiet hours)\". \"What happened\" gets \"Quiet hours began: Quiet\" and \"Quiet hours ended: Cool again\" or \"Quiet hours ended: the Mac has the fans again\". The same time twice means no quiet hours.",
            "Good to know: quiet hours last as long as the hours, whatever the \"For\" line says. Your own tap during the hours wins until they are over. If the Mac gets too hot (100\u{00B0}), it gets the fans and the hours leave them alone for that night. On battery, with \"On battery: the Mac decides\" on, the Mac keeps the fans. During a call's Quiet nothing changes, and the hours take over when the call ends. After sleep inside the hours, Quiet comes on again. Quiet hours need the fan control helper to be in place.",
            "Fixed: the Graphics temperature sometimes read about 9\u{00B0} while that part of the chip was asleep. Such a figure is now no reading: the panel keeps the last true figure and the graph has a small gap there.",
            "Unchanged: the small graph in the panel, the six choices and the helper. No new password is needed.",
            "Changed: How it works has new words in The panel, The graphs, The level lines, The heat notice, What happened, Settings, Good to know and What the app remembers, and new sections \"Pointing at a graph\", \"Battery heat notice\", \"Quiet hours\" and \"The last 7 days\". Signs in this app has three new signs: Teal (the power the whole Mac uses), a pale blue stretch in the Fan speed graph (a choice of yours was on) and a thin upright solid line that follows the pointer (the moment you point at). A button in full colour now also covers a time pick, a graph shown and the heat notice level. A pale button also covers a hidden graph. Coral now also covers the Storage and Case graphs. Amber in a graph is now the heat notice level you picked (Chip) and Apple's 35\u{00B0} (Battery).",
        ]),
        Release(version: "0.4.1", date: "25 Nov 2026", items: [
            "New: two rough lines in the Chip temperature graph, dotted and grey, with grey words at the left end. The true lines are solid and coloured with their words at the right end, so the two kinds cannot be mixed up. \"Reports: fans speed up at about 95\u{00B0}\" is drawn at 95\u{00B0}. \"Reports: chip slows itself at about 100\u{00B0} to 110\u{00B0}\" is drawn at 105\u{00B0}, the middle of that range.",
            "Good to know: these two figures come from what other owners of this kind of Mac have written on the web. They are not from Apple and not measured on this Mac. They may be wrong for this Mac. For comparison, measured on this Mac on 25 Nov 2026: in Automatic the fans were still at about 1,590 turns a minute with the chip at 90\u{00B0} to 93\u{00B0}. When the app has learned the green line \"Fans at full in Automatic \u{00B7} seen at N\u{00B0}\" on this Mac, trust that one over the reports.",
            "New: a sign in the guide, \"Dotted grey line in a graph\": a rough figure from owners' reports, not from Apple and not measured on this Mac.",
            "Changed: the scale of the Chip graph now reaches up to at least 120\u{00B0} (before: 110\u{00B0}), to make room for the rough lines. The Graphics graph stays at 110\u{00B0} and the Battery graph at 50\u{00B0}.",
            "Changed: the last line at the bottom of the large graph window now reads \"Dotted grey = owners' reports, not Apple \u{00B7} no figure for when the Mac turns itself off\". Before: \"Apple gives no figure for when the Mac turns itself off, so there is no line for it.\"",
            "Good to know: there is still no line for \"the Mac turns itself off\": not even a report gives a figure. The Graphics and Battery graphs are unchanged and have no rough lines.",
            "Good to know: the update from 0.4 needs no password, because the helper did not change.",
        ]),
        Release(version: "0.4", date: "25 Nov 2026", items: [
            "New: graphs for all three temperatures. Before, the large graph window had two graphs (Chip temperature and Fan speed), and the app kept only the chip temperature. Now the app notes the chip, the graphics and the battery temperature every 5 seconds and keeps six hours of all three. Readings kept before 0.4 have only the chip, so the Graphics and Battery graphs start empty and fill from the update on.",
            "Changed: the large graph window now has four graphs, from top to bottom: Chip temperature, Graphics temperature, Battery temperature and Fan speed. The window is taller. The 15 minutes, 1 hour and 6 hours pick, \"Done\" and Escape are as before. Each temperature heading shows the figure right beside its name, then a small grey mark with the usual range, for example \"Chip temperature 56\u{00B0}\" and \"usual here 41\u{00B0} to 78\u{00B0}\".",
            "New: level lines, thin solid flat lines across a temperature graph, each with its words at the right end. Chip: amber \"Heat notice 90\u{00B0}\" (from here the heat notice counts its 5 minutes) and red \"Too hot 100\u{00B0}\" (the app's own safety rule: the hottest core at 100\u{00B0} for 15 seconds, not in Full, hands the fans back to the Mac). Battery: amber \"Apple's limit for the room 35\u{00B0}\" (Apple says to use a Mac laptop where it is 10\u{00B0} to 35\u{00B0}; that is the room, not the battery itself, but it is the only figure Apple gives) and red \"Charging may stop about 44\u{00B0}\" (measured once by an independent tester on another Apple laptop, not an Apple figure, so it says \"about\"). Graphics has no level line: Apple gives no figures and the app has no rule for it.",
            "New: a green line that the app learns on this Mac, \"Fans at full in Automatic \u{00B7} seen at N\u{00B0}\". The app notes the chip temperature at the moment the Mac itself takes the fans to full (90 % of the top speed or more), in Automatic or while Quiet lets the fans rest. Each new time replaces the old figure. Until that has happened there is no green line, and grey words beside the heading say \"fans at full in Automatic: not seen yet\".",
            "New: a soft grey band in all three temperature graphs: the usual range on this Mac. The small grey mark beside the heading, with words such as \"usual here 41\u{00B0} to 78\u{00B0}\", says what it is. It is the range that holds the middle 80 % of all readings kept (up to six hours). It appears after 30 minutes of readings.",
            "Changed: the scale of the Chip and Graphics graphs now always reaches up to at least 110\u{00B0}, and the Battery graph up to at least 50\u{00B0}, so the level lines are always in view. Before, the scale fitted the readings only.",
            "Changed: the names of the choice changes (\"Cool\", \"Automatic\") at the dashed lines moved from the Chip graph to the Fan speed graph, to leave room for the level words.",
            "Good to know: Apple publishes no figure for the temperature at which the chip slows itself, at which the Mac takes the fans to full, or at which the Mac turns itself off. So there is no line for \"the Mac turns itself off\", because any figure would be made up. The window says so in one line at the bottom: \"Apple gives no figure for when the Mac turns itself off, so there is no line for it.\" Measured on this Mac on 25 Nov 2026: in Automatic the fans were still at about 1,590 turns a minute with the chip at 90\u{00B0} to 93\u{00B0}.",
            "Unchanged: the small graph in the panel still shows the chip and the fan speed for 15 minutes.",
            "Changed: How it works has new words in \"The graphs\" and a new section \"The level lines\", and \"What the app remembers\" names the new figure. Signs in this app has two new signs: a red line in a graph (too hot: from here something protects itself) and a grey band in a graph (the usual range on this Mac). Amber now also covers the line in a graph from where a temperature needs your eye. Green now also covers the line where the Mac itself took the fans to full. Coral now covers the line of all three temperature graphs.",
            "No new password is needed: the small helper did not change."
        ]),
        Release(version: "0.3.1", date: "25 Nov 2026", items: [
            "New: another app can ask for a choice for a time of its own. Before, a choice asked for from outside (the fan keys of AMS Deck Mate) always lasted as long as your pick in the \"For\" line said, so with \"Until I change\" a press on the Cool key stayed on for good. Now the Cool and Full keys of AMS Deck Mate (from its version 0.19) ask for 10 minutes. Then the Mac gets the fans back by itself and the choice goes to Automatic.",
            "While such a time runs, the \"For\" line shows it in full colour (10 min) and the status line counts down, for example \"You decide: Cool \u{00B7} 8 min left\". When it is up, the line shows your own pick again. Your pick is never changed by another app.",
            "A tap on a time in the \"For\" line while such a time runs takes over at once, also a tap on the pick you already had.",
            "Choices you tap in the panel itself work as before: they last as long as the \"For\" line says.",
            "No new password is needed: the small helper did not change."
        ]),
        Release(version: "0.3", date: "24 Nov 2026", items: [
            "New: Quiet lets the fans stop. Before (0.2), Quiet always held the fans at their lowest running speed (1,499 turns a minute on this Mac, or your own Quiet speed from Settings, 0 % to 40 %). But left alone, in Automatic, this Mac stops its fans completely (0 turns) when the chip is cool, at around 63\u{00B0}. So Automatic could be quieter than Quiet. Now, while Quiet is on and the chip is cool, the fans may stop too.",
            "How it works: the app can never set a fan below its lowest running speed. So when the chip has been at 60\u{00B0} or less for 30 seconds, Quiet gives the fans to the Mac, which then stops them when it finds it cool enough. The fans are resting.",
            "Quiet is never louder than before: the moment the Mac runs a fan more than 150 turns faster than your Quiet speed for 4 seconds, the app takes the fans again and holds them at your Quiet speed, exactly as Quiet always did. After taking them again, the app holds them for at least 5 minutes before they may rest again, so the fans do not switch back and forth.",
            "New: while the fans rest, the status line in the panel says \"You decide: Quiet \u{00B7} fans resting\". The Quiet button stays in full colour and the menu bar mark stays blue: blue means your choice is on, here Quiet including its rest.",
            "New: a switch in Settings, in \"Your speeds\": \"Quiet lets the fans stop\". It is on at first. Off means Quiet behaves as in 0.2: always your Quiet speed, never stopped. If you switch it off in the middle of a rest, your Quiet speed comes back at once.",
            "It works the same with \"Quiet during calls\" (that rule switches to Quiet, so the fans may rest then too) and with your own Quiet speed.",
            "Changed: in the graphs a rest shows as the speed line going down to 0 while Quiet is on. This is true, not a fault.",
            "Nothing else changed. All safety rules stay: too hot (100\u{00B0} for 15 seconds) hands the fans back to the Mac, the time \"For 10 min, 30 min or 1 hour\" still ends Quiet, and battery, sleep and quit behave as before.",
            "Changed: How it works has new words in the sections on Quiet, Your own Quiet and Cool, Quiet during calls, the graphs, Settings and Good to know: the limits (it said Automatic can be quieter than Quiet; that is now only true with the new switch off). Signs in this app: blue now also covers the rest.",
            "No new password is needed: the small helper did not change."
        ]),
        Release(version: "0.2", date: "24 Nov 2026", items: [
            "New: graphs. At the bottom of the panel a small graph shows the last 15 minutes: a coral line for the chip temperature, a blue line for the fan speed (the average of both fans) and a dashed line at every moment the choice changed.",
            "New: a tap on the small graph opens the large graph in its own window. Pick 15 minutes, 1 hour or 6 hours. The temperature is above and the speed of each fan (Left, Right) below. Each dashed line carries the name of the change, for example \"Cool\". \"Done\" or Escape closes it.",
            "New: the app notes one reading every 5 seconds, also while the panel is closed, and keeps six hours. The readings survive quitting the app and are saved on this Mac only. While the Mac sleeps or the app is not running there are no readings, and the line has a gap there.",
            "New: a choice for a limited time. Under the buttons is a line \"For\": 10 min, 30 min, 1 hour or Until I change. It works with every choice except Automatic. When the time is up the Mac gets the fans back by itself and the choice goes to Automatic. The status line counts down, for example \"You decide: Cool \u{00B7} 8 min left\". Tapping a choice, or a time, starts the time afresh. Your pick is remembered (\"Until I change\" at first).",
            "Changed: hovering over the fan mark in the menu bar now also gives the figures, for example \"Left 1,776 \u{00B7} Right 1,868 \u{00B7} Chip 72\u{00B0}\", under the line that says who decides. The mark itself stays without a figure.",
            "New: your own Quiet and Cool. Settings has \"Your speeds\": Quiet from 0 % to 40 % (0 % at first, the lowest speed) and Cool from 30 % to 90 % (50 % at first, half speed), in steps of 5. The words under the two buttons follow: \"lowest speed\", \"half speed\" or for example \"40 % speed\".",
            "New: a heat notice. While the Mac decides, a notification tells you when the chip has been at 90\u{00B0} or more for 5 minutes, with the button \"Switch to Cool\". At most once every 30 minutes. A switch in Settings (\"Heat notice\") turns it off. It is on at first.",
            "New: Quiet during calls. A switch in Settings, off at first. When an app has used the microphone for 15 seconds (a video call; a short dictation does not count), the app switches to Quiet and the status line says \"You decide: Quiet (during a call)\". When the microphone has been free for 30 seconds, the choice you had before comes back, Automatic too. If you tap a choice yourself during the call, your tap wins. A video call makes the Mac warm, so with the fans at their lowest it may reach the too-hot limit, and then the Mac gets the fans back as always.",
            "New: on battery, the Mac decides. A switch in Settings, on at first. When you pull the power cable while a choice is on, the fans go back to the Mac and the status line says \"The Mac decides (on battery)\". When the cable is back in, your choice comes back. If you tap a choice yourself while on battery, your tap wins.",
            "New: \"What happened\", a fourth tab in Settings. It lists the last 20 things the app did, newest first, each with its time, in plain words: for example \"Cool for 10 minutes\", \"The time was up: the Mac has the fans again\", \"Too hot (101\u{00B0}): the Mac has the fans again\", \"A call began: Quiet\", \"On battery: the Mac has the fans again\". Kept on this Mac only.",
            "New: \"Choice back after sleep\", a switch in Settings, off at first. Sleep still hands the fans to the Mac. With the switch on, the app puts your choice back about 5 seconds after the Mac wakes. Restart and quit still always hand the fans to the Mac.",
            "Changed: the settings window now has four tabs (Settings, What happened, How it works, What's new). How it works has new sections for all of the above, and Signs in this app has one new sign: a dashed line in a graph means the moment the choice changed. Coral and blue now also cover the graph's lines.",
            "Fixed: after an unexpected stop the app came back at once and said \"The Mac decides\" while the helper still held the fans at the old speed for up to 20 seconds. Now the app asks the helper to give the fans back the moment it starts, so the screen and the fans agree. The helper did not change, so no password is needed for this update."
        ]),
        Release(version: "0.1.1", date: "24 Nov 2026", items: [
            "Fixed: in 0.1 no choice could be switched on. The Mac hands a fan over a few hundredths of a second after it is asked, and the helper looked at once, saw \"not yet\" and gave up. The helper now waits for the hand-over, looking every hundredth of a second for up to 1.5 seconds, and asks again every 0.3 seconds.",
            "Fixed: after a failed try, a fan could stay held at its last speed without the app knowing. The helper now hands over all fans first and only then sets the speeds.",
            "Changed: giving the fans back is now thorough. The helper gives back every fan, keeps looking for one more second and gives back again any fan that turned up as held late.",
            "Changed: if the Mac takes a fan back by itself, the helper notices and takes it over again. It notes this in its log.",
            "Changed: because the helper is new, the app asks once more for the Mac's password. An amber note says \"The fan helper is from an older version. It needs your OK once more.\" with the button \"Update the helper\u{2026}\".",
            "Fixed: the Mac now takes a speed directly. Tested on this Mac: the left fan took 3,000 and went from about 1,520 to about 2,360 turns a minute within two seconds."
        ]),
        Release(version: "0.1", date: "24 Nov 2026", items: [
            "New: the first version. AMS Fan Menu lives in the menu bar of your Mac and lets you choose how fast the fans turn. The Mac has no setting of its own for this.",
            "New: the menu bar shows a small hand-drawn fan mark. It is black (white at night) while the Mac decides and blue while the app runs the fans. Hovering says which.",
            "New: if the Mac moves the mark out of sight to the far left, the app puts it back after 10 seconds.",
            "New: the panel shows how fast each fan turns now, for example \"Left 1,776 \u{00B7} Right 1,868\", fresh every second while the panel is open.",
            "New: the panel shows the temperatures of the chip, the graphics and the battery, and a status line such as \"The Mac decides\" or \"You decide: Cool\".",
            "New: six choices: Automatic, Quiet, Cool, Full, My speed and Follow temperature. The one in use is in full colour with white words, and the others are pale.",
            "New: My speed has a slider from 0 % (lowest) to 100 % (top). Both fans move together, each within its own range.",
            "New: Follow temperature has two sliders, Start (first 65\u{00B0}) and Full (first 95\u{00B0}), in steps of 5\u{00B0} and always at least 10\u{00B0} apart. It changes speed only when the change is at least 100 turns, so the fans do not keep hunting.",
            "New: setting the fans needs your OK once. An amber note with a button \"Allow fan control\u{2026}\" asks for your Mac password in the Mac's own dialog, and installs a small helper that takes orders only from this app. Settings can remove it again.",
            "New: four safety rules. Too hot (100\u{00B0} or more for 15 seconds) hands the fans back and sends a notification. Quit, sleep and restart hand them back. If the app stops unexpectedly, the helper gives them back after 20 seconds. A speed stays inside each fan's own range.",
            "New: the app repeats the choice in use to the Mac every 3 seconds, because the Mac would otherwise take the fans back.",
            "New: the app remembers your My speed percentage and your Start and Full temperatures. The choice in use is never remembered.",
            "New: Settings has three tabs (Settings, How it works, What's new), \"Open at login\", the helper's state with \"Remove the helper\u{2026}\", Quit and Done. The version number is shown.",
            "New: a diary of what the app did (times, choices, speeds, nothing personal) is kept on this Mac only."
        ])
    ]
}
